//! 🤝️ Borrowed SFNT Latin pair positioning preserves original font bytes without shaping cache ownership.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum FontPairError{Malformed,Unsupported}
type Result<T>=std::result::Result<T,FontPairError>;
#[derive(Clone,Copy)]
struct Span<'a>(&'a[u8]);
impl<'a> Span<'a>{
 fn u16(self,at:usize)->Result<u16>{let b=self.0.get(at..at.checked_add(2).ok_or(FontPairError::Malformed)?).ok_or(FontPairError::Malformed)?;Ok(u16::from_be_bytes([b[0],b[1]]))}
 fn u32(self,at:usize)->Result<u32>{let b=self.0.get(at..at.checked_add(4).ok_or(FontPairError::Malformed)?).ok_or(FontPairError::Malformed)?;Ok(u32::from_be_bytes([b[0],b[1],b[2],b[3]]))}
 fn from(self,at:usize)->Result<Self>{Ok(Self(self.0.get(at..).ok_or(FontPairError::Malformed)?))}
 fn table(self,tag:u32)->Result<Option<Self>>{let count=usize::from(self.u16(4)?);if count>128{return Err(FontPairError::Unsupported)}for n in 0..count{let at=12+n*16;if self.u32(at)?==tag{let offset=self.u32(at+8)?as usize;let end=offset.checked_add(self.u32(at+12)?as usize).ok_or(FontPairError::Malformed)?;return Ok(Some(Self(self.0.get(offset..end).ok_or(FontPairError::Malformed)?)))}}Ok(None)}
}
/// 🔤️ A font pair reader owns only immutable source spans and scalar directory coordinates.
#[derive(Clone,Copy)]
pub struct BorrowedFontPair<'a>{bytes:&'a[u8],cmap:Span<'a>,mapping:usize,format:u16,units:u16,gpos:Option<Span<'a>>,kern:Option<Span<'a>>}
impl<'a> BorrowedFontPair<'a>{
 pub fn new(bytes:&'a[u8])->Result<Self>{
  let r=Span(bytes);if !matches!(r.u32(0)?,0x00010000|0x74727565){return Err(FontPairError::Unsupported)}let head=r.table(0x68656164)?.ok_or(FontPairError::Malformed)?;let units=head.u16(18)?;if units==0{return Err(FontPairError::Malformed)}let cmap=r.table(0x636d6170)?.ok_or(FontPairError::Malformed)?;let count=usize::from(cmap.u16(2)?);if count>128{return Err(FontPairError::Unsupported)}let(mut mapping,mut format)=(0,0);for n in 0..count{let at=4+n*8;let platform=cmap.u16(at)?;let encoding=cmap.u16(at+2)?;if platform!=0&&(platform!=3||!matches!(encoding,1|10)){continue}let offset=cmap.u32(at+4)?as usize;let candidate=cmap.u16(offset)?;if candidate==12||(candidate==4&&format==0){mapping=offset;format=candidate}}
  if format==0{return Err(FontPairError::Unsupported)}Ok(Self{bytes,cmap,mapping,format,units,gpos:r.table(0x47504f53)?,kern:r.table(0x6b65726e)?})
 }
 pub fn original_bytes(&self)->&'a[u8]{self.bytes}
 pub fn units_per_em(&self)->u16{self.units}
 pub fn glyph(&self,scalar:char)->Result<u16>{
  let r=self.cmap.from(self.mapping)?;let cp=scalar as u32;if self.format==12{let mut lo=0usize;let mut hi=r.u32(12)?as usize;if hi>65536{return Err(FontPairError::Unsupported)}while lo<hi{let n=(lo+hi)/2;let at=16+n*12;let from=r.u32(at)?;let to=r.u32(at+4)?;if cp<from{hi=n}else if cp>to{lo=n+1}else{return u16::try_from(r.u32(at+8)?.checked_add(cp-from).ok_or(FontPairError::Malformed)?).map_err(|_|FontPairError::Malformed)}}return Ok(0)}
  if cp>65535{return Ok(0)}let count=usize::from(r.u16(6)?/2);let(mut lo,mut hi)=(0,count);while lo<hi{let n=(lo+hi)/2;let end=u32::from(r.u16(14+n*2)?);let start=u32::from(r.u16(16+count*2+n*2)?);if cp<start{hi=n}else if cp>end{lo=n+1}else{let delta=r.u16(16+count*4+n*2)?;let at=16+count*6+n*2;let offset=usize::from(r.u16(at)?);return if offset==0{Ok((cp as u16).wrapping_add(delta))}else{let glyph=r.u16(at+offset+(cp-start)as usize*2)?;Ok(if glyph==0{0}else{glyph.wrapping_add(delta)})}}}Ok(0)
 }
 pub fn pair_units(&self,left:char,right:char)->Result<i32>{let(left,right)=(self.glyph(left)?,self.glyph(right)?);if left==0||right==0{return Ok(0)}if let Some(gpos)=self.gpos{let(found,value)=gpos_pair(gpos,left,right)?;if found{return Ok(value)}}self.kern.map_or(Ok(0),|r|kern_pair(r,left,right))}
 pub fn pair_em(&self,left:char,right:char)->Result<f32>{Ok(self.pair_units(left,right)?as f32/f32::from(self.units))}
}
fn coverage(r:Span<'_>,glyph:u16)->Result<Option<usize>>{let count=usize::from(r.u16(2)?);let(mut lo,mut hi)=(0,count);match r.u16(0)?{1=>{while lo<hi{let n=(lo+hi)/2;let g=r.u16(4+n*2)?;if glyph<g{hi=n}else if glyph>g{lo=n+1}else{return Ok(Some(n))}}},2=>{while lo<hi{let n=(lo+hi)/2;let at=4+n*6;let from=r.u16(at)?;let to=r.u16(at+2)?;if glyph<from{hi=n}else if glyph>to{lo=n+1}else{return Ok(Some(usize::from(r.u16(at+4)?)+usize::from(glyph-from)))}}},_=>return Err(FontPairError::Unsupported)}Ok(None)}
fn class(r:Span<'_>,glyph:u16)->Result<usize>{match r.u16(0)?{1=>{let from=r.u16(2)?;let count=r.u16(4)?;Ok(if glyph>=from&&glyph-from<count{usize::from(r.u16(6+usize::from(glyph-from)*2)?)}else{0})},2=>{let(mut lo,mut hi)=(0,usize::from(r.u16(2)?));while lo<hi{let n=(lo+hi)/2;let at=4+n*6;let from=r.u16(at)?;let to=r.u16(at+2)?;if glyph<from{hi=n}else if glyph>to{lo=n+1}else{return Ok(usize::from(r.u16(at+4)?))}}Ok(0)},_=>Err(FontPairError::Unsupported)}}
fn value(r:Span<'_>,at:usize,format:u16)->Result<i32>{if format&0xff00!=0{return Err(FontPairError::Unsupported)}if format&4==0{return Ok(0)}Ok(i32::from(r.u16(at+usize::try_from((format&3).count_ones()).unwrap()*2)?as i16))}
fn pair_subtable(r:Span<'_>,left:u16,right:u16)->Result<Option<i32>>{
 let Some(index)=coverage(r.from(usize::from(r.u16(2)?))?,left)?else{return Ok(None)};let f1=r.u16(4)?;let f2=r.u16(6)?;let n1=f1.count_ones()as usize*2;let n2=f2.count_ones()as usize*2;
 match r.u16(0)?{1=>{if index>=usize::from(r.u16(8)?){return Err(FontPairError::Malformed)}let set=r.from(usize::from(r.u16(10+index*2)?))?;let(mut lo,mut hi)=(0,usize::from(set.u16(0)?));while lo<hi{let n=(lo+hi)/2;let at=2+n*(2+n1+n2);let glyph=set.u16(at)?;if right<glyph{hi=n}else if right>glyph{lo=n+1}else{return Ok(Some(value(set,at+2,f1)?+value(set,at+2+n1,f2)?))}}Ok(None)},2=>{let c1=class(r.from(usize::from(r.u16(8)?))?,left)?;let c2=class(r.from(usize::from(r.u16(10)?))?,right)?;let count1=usize::from(r.u16(12)?);let count2=usize::from(r.u16(14)?);if c1>=count1||c2>=count2{return Err(FontPairError::Malformed)}let at=16+(c1*count2+c2)*(n1+n2);Ok(Some(value(r,at,f1)?+value(r,at+n1,f2)?))},_=>Err(FontPairError::Unsupported)}
}
fn script(r:Span<'_>)->Result<Option<Span<'_>>>{let count=usize::from(r.u16(0)?);if count>128{return Err(FontPairError::Unsupported)}let mut fallback=None;for n in 0..count{let at=2+n*6;let tag=r.u32(at)?;if tag==0x6c61746e{return Ok(Some(r.from(usize::from(r.u16(at+4)?))?))}if tag==0x44464c54{fallback=Some(r.from(usize::from(r.u16(at+4)?))?)}}Ok(fallback)}
fn kern_lookup(features:Span<'_>,lang:Span<'_>,index:usize)->Result<bool>{let count=usize::from(lang.u16(4)?);if count>128{return Err(FontPairError::Unsupported)}for n in 0..=count{let feature=if n==count{lang.u16(2)?}else{lang.u16(6+n*2)?};if feature==0xffff{continue}if feature>=features.u16(0)?{return Err(FontPairError::Malformed)}let at=2+usize::from(feature)*6;if features.u32(at)?!=0x6b65726e{continue}let record=features.from(usize::from(features.u16(at+4)?))?;let count=usize::from(record.u16(2)?);if count>128{return Err(FontPairError::Unsupported)}for n in 0..count{if usize::from(record.u16(4+n*2)?)==index{return Ok(true)}}}Ok(false)}
fn gpos_pair(r:Span<'_>,left:u16,right:u16)->Result<(bool,i32)>{
 let Some(script)=script(r.from(usize::from(r.u16(4)?))?)?else{return Ok((false,0))};let lang=usize::from(script.u16(0)?);if lang==0{return Ok((false,0))}let lang=script.from(lang)?;let features=r.from(usize::from(r.u16(6)?))?;let lookups=r.from(usize::from(r.u16(8)?))?;let count=usize::from(lookups.u16(0)?);if count>128{return Err(FontPairError::Unsupported)}let(mut found,mut total)=(false,0i32);
 for n in 0..count{if !kern_lookup(features,lang,n)?{continue}found=true;let lookup=lookups.from(usize::from(lookups.u16(2+n*2)?))?;let kind=lookup.u16(0)?;let count=usize::from(lookup.u16(4)?);if count>128{return Err(FontPairError::Unsupported)}for n in 0..count{let mut sub=lookup.from(usize::from(lookup.u16(6+n*2)?))?;let mut kind=kind;if kind==9{if sub.u16(0)?!=1{return Err(FontPairError::Unsupported)}kind=sub.u16(2)?;sub=sub.from(sub.u32(4)?as usize)?}if kind!=2{return Err(FontPairError::Unsupported)}if let Some(value)=pair_subtable(sub,left,right)?{total=total.checked_add(value).ok_or(FontPairError::Malformed)?;break}}}Ok((found,total))
}
fn kern_pair(r:Span<'_>,left:u16,right:u16)->Result<i32>{if r.u16(0)?!=0{return Err(FontPairError::Unsupported)}let mut at=4;let mut total=0i32;let count=usize::from(r.u16(2)?);if count>128{return Err(FontPairError::Unsupported)}for _ in 0..count{let sub=r.from(at)?;let length=usize::from(sub.u16(2)?);if length<6{return Err(FontPairError::Malformed)}let flags=sub.u16(4)?;if flags&1!=0&&flags>>8==0{let(mut lo,mut hi)=(0,usize::from(sub.u16(6)?));let key=(u32::from(left)<<16)|u32::from(right);while lo<hi{let n=(lo+hi)/2;let pos=14+n*6;let value=sub.u32(pos)?;if key<value{hi=n}else if key>value{lo=n+1}else{let value=i32::from(sub.u16(pos+4)?as i16);total=if flags&8!=0{value}else{total.checked_add(value).ok_or(FontPairError::Malformed)?};break}}}at=at.checked_add(length).ok_or(FontPairError::Malformed)?}Ok(total)}
